using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;
using Microsoft.Extensions.Options;
using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Net.Http;
using System.Threading;
using System.Threading.Tasks;

namespace MeridianStudio.Implementation.IntegrateWithCmlDocumentRepositories
{
    public sealed record DocumentRepositoryOptions
    {
        public required string ApiEndpoint { get; init; }
        public required string ApiKey { get; init; }
        public int MaxConcurrentRequests { get; init; } = 10;
    }

    public sealed record DocumentMetadata(string Id, string FileName, DateTime LastModified, long Size);

    public sealed record DocumentContent(string Id, string Content);

    public sealed record RepositoryDocumentRequest(string DocumentId);

    public sealed record RepositoryDocumentResponse(DocumentContent? Content, string ErrorMessage = "");

    public interface IDocumentRepositoryClient
    {
        Task<IEnumerable<DocumentMetadata>> ListDocumentsAsync(CancellationToken cancellationToken = default);
        Task<RepositoryDocumentResponse> GetDocumentContentAsync(RepositoryDocumentRequest request, CancellationToken cancellationToken = default);
    }

    public sealed class DefaultDocumentRepositoryClient : IDocumentRepositoryClient
    {
        private readonly HttpClient _httpClient;
        private readonly ILogger<DefaultDocumentRepositoryClient> _logger;
        private readonly DocumentRepositoryOptions _options;

        public DefaultDocumentRepositoryClient(HttpClient httpClient, ILogger<DefaultDocumentRepositoryClient> logger, IOptions<DocumentRepositoryOptions> options)
        {
            _httpClient = httpClient ?? throw new ArgumentNullException(nameof(httpClient));
            _logger = logger ?? throw new ArgumentNullException(nameof(logger));
            _options = options.Value ?? throw new ArgumentNullException(nameof(options));

            _httpClient.BaseAddress = new Uri(_options.ApiEndpoint);
            _httpClient.DefaultRequestHeaders.Add("X-Api-Key", _options.ApiKey);
        }

        public async Task<IEnumerable<DocumentMetadata>> ListDocumentsAsync(CancellationToken cancellationToken = default)
        {
            _logger.LogInformation("Listing documents from repository.");
            try
            {
                var response = await _httpClient.GetAsync("/documents", cancellationToken);
                response.EnsureSuccessStatusCode();
                var metadata = await response.Content.ReadFromJsonAsync<List<DocumentMetadata>>(cancellationToken: cancellationToken);
                return metadata ?? Enumerable.Empty<DocumentMetadata>();
            }
            catch (HttpRequestException ex)
            {
                _logger.LogError(ex, "Failed to list documents from repository.");
                return Enumerable.Empty<DocumentMetadata>();
            }
        }

        public async Task<RepositoryDocumentResponse> GetDocumentContentAsync(RepositoryDocumentRequest request, CancellationToken cancellationToken = default)
        {
            _logger.LogInformation("Retrieving content for document ID: {DocumentId}", request.DocumentId);
            if (string.IsNullOrWhiteSpace(request.DocumentId))
            {
                _logger.LogWarning("Invalid DocumentId provided.");
                return new RepositoryDocumentResponse(null, "Invalid DocumentId provided.");
            }

            try
            {
                var response = await _httpClient.GetAsync($"/documents/{request.DocumentId}/content", cancellationToken);
                if (!response.IsSuccessStatusCode)
                {
                    _logger.LogError("Failed to retrieve content for document ID: {DocumentId}. Status code: {StatusCode}", request.DocumentId, response.StatusCode);
                    return new RepositoryDocumentResponse(null, $"Failed to retrieve content. Status: {response.StatusCode}");
                }

                var content = await response.Content.ReadAsStringAsync(cancellationToken);
                return new RepositoryDocumentResponse(new DocumentContent(request.DocumentId, content));
            }
            catch (HttpRequestException ex)
            {
                _logger.LogError(ex, "Network error retrieving content for document ID: {DocumentId}", request.DocumentId);
                return new RepositoryDocumentResponse(null, "Network error occurred.");
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Unexpected error retrieving content for document ID: {DocumentId}", request.DocumentId);
                return new RepositoryDocumentResponse(null, "An unexpected error occurred.");
            }
        }
    }

    public static class DocumentRepositoryServiceCollectionExtensions
    {
        public static IServiceCollection AddDocumentRepositoryClient(this IServiceCollection services, Action<DocumentRepositoryOptions> configureOptions)
        {
            services.AddOptions<DocumentRepositoryOptions>().Configure(configureOptions);
            services.AddHttpClient<IDocumentRepositoryClient, DefaultDocumentRepositoryClient>();
            return services;
        }
    }
}
